package thaumcraft.verification;

import com.mojang.authlib.GameProfile;
import java.util.*;
import java.util.function.BiConsumer;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.*;
import net.minecraft.world.effect.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.ai.goal.*;
import net.minecraft.world.entity.projectile.SmallFireball;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.common.util.FakePlayer;
import thaumcraft.api.aspects.*;
import thaumcraft.entities.*;
import thaumcraft.items.*;
import thaumcraft.registry.*;

/** Real entity state, AI actions, stack conservation, taming, area damage and menu transactions. */
final class CultistPechVerification {
    static void run(ServerLevel level,BiConsumer<Boolean,String> check)throws Exception{
        var origin=new BlockPos(3820,160,80);level.getChunkAt(origin);for(int x=-12;x<=12;x++)for(int z=-12;z<=12;z++){level.setBlock(origin.offset(x,-1,z),Blocks.STONE.defaultBlockState(),2);for(int y=0;y<5;y++)level.setBlock(origin.offset(x,y,z),Blocks.AIR.defaultBlockState(),2);}var cleanup=new ArrayList<Entity>();
        try{
            var knight=R5Entities.CULTIST_KNIGHT.get().create(level);var cleric=R5Entities.CULTIST_CLERIC.get().create(level);var pech=R5Entities.PECH.get().create(level);for(var mob:List.of(knight,cleric,pech)){cleanup.add(mob);if(mob.getAttribute(ChampionSystem.MODIFIER)!=null)mob.getAttribute(ChampionSystem.MODIFIER).setBaseValue(-1);mob.moveTo(origin.getCenter());mob.setNoAi(true);level.addFreshEntity(mob);}
            check.accept(knight.getMaxHealth()==36&&cleric.getMaxHealth()==30&&pech.getMaxHealth()==30,"original knight36/cleric30/Pech30 health");check.accept(knight.getAttributeValue(Attributes.ATTACK_DAMAGE)==4&&knight.getAttributeValue(Attributes.MOVEMENT_SPEED)==.3&&pech.getAttributeValue(Attributes.ATTACK_DAMAGE)==6&&pech.getAttributeValue(Attributes.MOVEMENT_SPEED)==.5,"original combat and movement attributes");check.accept(pech.getBbWidth()==.6f&&pech.getBbHeight()==1.8f&&pech.getEyeHeight()==1.8f*.66f,"original Pech body and eye dimensions");check.accept(knight.isAlliedTo(cleric)&&cleric.isAlliedTo(knight)&&!knight.isAlliedTo(pech),"cultist cross-class ally recognition");
            knight.finalizeSpawn(level,level.getCurrentDifficultyAt(origin),MobSpawnType.COMMAND,null);check.accept(!knight.getItemBySlot(EquipmentSlot.CHEST).isEmpty()&&!knight.getItemBySlot(EquipmentSlot.FEET).isEmpty()&&!knight.getMainHandItem().isEmpty(),"knight spawn actually equips plate, boots and sword");cleric.finalizeSpawn(level,level.getCurrentDifficultyAt(origin),MobSpawnType.COMMAND,null);check.accept(cleric.getItemBySlot(EquipmentSlot.HEAD).is(R5Content.CULTIST_ARMOR.get("cultist_robe_helmet").get())&&cleric.getItemBySlot(EquipmentSlot.LEGS).is(R5Content.CULTIST_ARMOR.get("cultist_robe_leggings").get()),"cleric spawn actually equips original robe");cleric.restrictTo(origin,8);cleric.setRitualist(true);check.accept(!cleric.removeWhenFarAway(10000)&&cleric.ritualHome().equals(origin),"ritualist does not despawn and home sync follows restriction");var saved=new CompoundTag();cleric.addAdditionalSaveData(saved);var restored=R5Entities.CULTIST_CLERIC.get().create(level);cleanup.add(restored);restored.readAdditionalSaveData(saved);check.accept(restored.isRitualist()&&restored.getRestrictCenter().equals(origin)&&restored.getRestrictRadius()==8,"cleric flags and home survive native NBT round trip");cleric.hurt(level.damageSources().generic(),1);check.accept(!cleric.isRitualist(),"damage interrupts altar ritual before hurt processing");
            var cow=EntityType.COW.create(level);cleanup.add(cow);cow.moveTo(origin.getCenter().add(0,0,1));cow.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);cow.setHealth(100);cow.setNoAi(true);level.addFreshEntity(cow);var selector=Mob.class.getDeclaredField("goalSelector");selector.setAccessible(true);var goals=(GoalSelector)selector.get(knight);var melee=goals.getAvailableGoals().stream().map(WrappedGoal::getGoal).filter(g->g.getClass().getName().equals("thaumcraft.entities.Cultist$Melee")).findFirst().orElseThrow();var timer=melee.getClass().getDeclaredField("attackTicks");timer.setAccessible(true);knight.setTarget(cow);melee.tick();check.accept(timer.getInt(melee)==10&&cow.getHealth()<100,"actual cultist melee goal strikes and starts original ten-tick cooldown");for(int i=0;i<9;i++)melee.tick();check.accept(timer.getInt(melee)==1,"melee remains gated through first nine ticks");cow.invulnerableTime=0;melee.tick();check.accept(timer.getInt(melee)==10,"melee strikes again on tenth tick");
            for(int branch=0;branch<2;branch++){long seed=0;while((net.minecraft.util.RandomSource.create(seed).nextFloat()>.66f)!=(branch==1))seed++;cleric.getRandom().setSeed(seed);cleric.performRangedAttack(cow,.5f);var orbs=level.getEntitiesOfClass(GolemOrb.class,cleric.getBoundingBox().inflate(8));var balls=level.getEntitiesOfClass(SmallFireball.class,cleric.getBoundingBox().inflate(8));check.accept(branch==1?orbs.size()==1&&orbs.get(0).red()&&orbs.get(0).getOwner()==cleric:balls.size()==3,"cleric native ranged branch "+(branch==1?"red homing orb":"three small fireballs"));cleanup.addAll(orbs);cleanup.addAll(balls);orbs.forEach(Entity::discard);balls.forEach(Entity::discard);}
            for(var entry:Map.of(Items.GOLD_INGOT,2,Items.GOLDEN_APPLE,2,Items.ENDER_PEARL,3,Items.DIAMOND,4,Items.EMERALD,5).entrySet())check.accept(pech.value(new ItemStack(entry.getKey()))==entry.getValue(),"source explicit Pech value "+entry.getKey());check.accept(pech.value(ManaBeanItem.of(Aspects.AIR))==1,"mana bean original value one");
            var bribe=new ItemStack(Items.EMERALD,7);long tameSeed=0;while(net.minecraft.util.RandomSource.create(tameSeed).nextInt(10)>=5)tameSeed++;pech.getRandom().setSeed(tameSeed);check.accept(pech.pickup(bribe).getCount()==6&&pech.tamed()&&pech.updateAINextTick,"valuable pickup consumes one item and tames with source probability");
            pech.loot.set(0,new ItemStack(Items.COBBLESTONE,60));var remainder=pech.pickup(new ItemStack(Items.COBBLESTONE,10));check.accept(remainder.isEmpty()&&pech.loot.get(0).getCount()==64&&pech.loot.get(1).getCount()==6,"Pech pack first fills partial stack then uses empty slot without item loss");for(int i=2;i<9;i++)pech.loot.set(i,new ItemStack(Items.DIRT,64));check.accept(!pech.canPickup(new ItemStack(Items.DIAMOND))&&!pech.removeWhenFarAway(10000),"full tamed pack rejects pickup and five occupied slots prevent far despawn");pech.anger(513);pech.variant(2);saved=new CompoundTag();pech.addAdditionalSaveData(saved);var loaded=R5Entities.PECH.get().create(level);cleanup.add(loaded);loaded.readAdditionalSaveData(saved);check.accept(loaded.variant()==2&&loaded.anger()==513&&loaded.tamed()&&loaded.loot.get(0).getCount()==64&&loaded.loot.get(8).getCount()==64&&loaded.updateAINextTick,"variant, short anger, tame and all nine original pack slots persist");
            var player=new FakePlayer(level,new GameProfile(UUID.randomUUID(),"PechTest"));cleanup.add(player);player.moveTo(origin.getCenter().add(3,0,0));level.addFreshEntity(player);pech.anger(0);pech.hurt(level.damageSources().playerAttack(player),1);check.accept(!pech.tamed()&&pech.anger()>=400&&pech.anger()<800&&pech.getTarget()==player&&loaded.anger()==513,"player hit untames victim with source400..799 anger and target");loaded.moveTo(origin.getCenter().add(3,0,1));level.addFreshEntity(loaded);loaded.tamed(true);pech.invulnerableTime=0;pech.hurt(level.damageSources().playerAttack(player),1);check.accept(!loaded.tamed()&&loaded.getTarget()==player&&loaded.anger()>=400,"native nearby Pech receive collective anger");
            var hit=PechBlast.class.getDeclaredMethod("onHit",HitResult.class);hit.setAccessible(true);cow.moveTo(origin.getCenter().add(8,0,0));cow.invulnerableTime=0;cow.setHealth(100);loaded.moveTo(cow.position());var blast=new PechBlast(level,pech,1,2,true);cleanup.add(blast);blast.moveTo(cow.position());float pechHealth=loaded.getHealth();hit.invoke(blast,new EntityHitResult(cow));check.accept(blast.isRemoved()&&cow.getHealth()==97&&loaded.getHealth()==pechHealth,"Pech blast applies strength+2 area damage, excludes every Pech and removes");check.accept(cow.getEffect(MobEffects.POISON).getDuration()==180&&cow.getEffect(MobEffects.POISON).getAmplifier()==1&&cow.getEffect(MobEffects.MOVEMENT_SLOWDOWN).getAmplifier()==2&&cow.getEffect(MobEffects.BLINDNESS).getDuration()==180,"nightshade applies three exact duration/amplifier effects");
            for(int variant=0;variant<3;variant++){var trades=PechTrades.inventory(level,variant);for(int tier=1;tier<=5;tier++){int required=tier;check.accept(trades.stream().anyMatch(t->t.tier()==required&&!t.stack().isEmpty()),"original Pech trade inventory variant"+variant+" has tier"+tier);}check.accept(trades.stream().anyMatch(t->t.stack().getItem() instanceof ManaBeanItem),"each Pech variant trades mana beans");}
            pech.tamed(true);pech.moveTo(player.position());pech.variant(0);var menu=new thaumcraft.menu.PechMenu(9,player.getInventory(),pech);menu.contents.setItem(0,ManaBeanItem.of(Aspects.AIR));level.random.setSeed(0);check.accept(menu.ready()&&menu.clickMenuButton(player,0)&&menu.contents.getItem(0).isEmpty(),"real Pech menu trade accepts valued offer and consumes exactly one");check.accept(java.util.stream.IntStream.range(1,5).anyMatch(i->!menu.contents.getItem(i).isEmpty()),"trade produces actual result stack in one of four slots");check.accept(!menu.clickMenuButton(player,0),"menu cannot trade without input or while results occupied");menu.removed(player);check.accept(!pech.trading,"closing trade resets NPC trading state");
            var focus=new ItemStack(R5Content.PECH_FOCUS.get());var item=(PechFocusItem)focus.getItem();check.accept(item.getVisCost(focus).size()==3&&item.getVisCost(focus).values().stream().allMatch(n->n==10)&&item.getActivationCooldown(focus)==250,"Pech focus original three ten-centivis costs and250ms cooldown");for(int rank=1;rank<=5;rank++)item.applyUpgrade(focus,rank==5?thaumcraft.api.wands.FocusUpgradeType.nightshade:thaumcraft.api.wands.FocusUpgradeType.frugal,rank);check.accept(item.getVisCost(focus).size()==6,"nightshade upgraded focus costs all six primals");
            check.accept(java.util.stream.IntStream.range(0,32).filter(i->ManaBeanItem.originalEffect(i)!=null).count()==23,"mana bean preserves32-slot original potion draw with23 populated entries");
        }finally{cleanup.forEach(Entity::discard);}
        PechIntegrationVerification.run(level,check);
    }
    private CultistPechVerification(){}
}
